LESSON_BANK = {
# UNIT I — OPERATIONAL AMPLIFIERS
"ideal-practical-opamp": {"worked_title":"Ideal model versus a practical device", "worked_steps":["For first-pass analysis, assume the op-amp operates with negative feedback and is not saturated.","Use the ideal rules: input currents are approximately zero and the two input terminals are at nearly equal voltage.","After calculating the output, check that it lies within the real device's output swing."], "example":"A closed-loop calculation predicts Vout = 14 V, but the selected op-amp is powered from ±12 V and cannot swing fully to either rail. The ideal calculation is not physically achievable; the output clips near the device's output limit.", "check":"Why can an ideal-model result be invalid for a practical op-amp?", "answer":"Because finite supply rails, output swing, bandwidth, slew rate, input common-mode range and current limits constrain real operation.", "pitfalls":["Assuming input terminals are equal without negative feedback.","Forgetting output saturation and common-mode limits."]},
"opamp-characteristics": {"worked_title":"CMRR calculation", "worked_steps":["Identify differential gain Ad and common-mode gain Ac from the question.","Calculate the ratio Ad/Ac using consistent units.","Convert the ratio to decibels with 20 log10(ratio)."], "example":"If Ad = 100,000 and Ac = 10, then CMRR = 10,000 and CMRR(dB) = 20 log10(10,000) = 80 dB.", "check":"Does a larger CMRR usually indicate better rejection of common-mode signals?", "answer":"Yes. A larger differential-to-common-mode gain ratio means common-mode input is less likely to appear at the output.", "pitfalls":["Using 10 log10 for a voltage-gain ratio.","Mixing gain values expressed in different units."]},
"opamp-dc-ac": {"worked_title":"Gain-bandwidth estimate", "worked_steps":["Read the closed-loop gain and the relevant gain-bandwidth product from the problem statement or datasheet.","For a single-pole approximation, divide the gain-bandwidth product by the closed-loop gain.","Treat the result as an estimate only within the device's valid operating conditions."], "example":"If a simplified model has a 1 MHz gain-bandwidth product and a closed-loop gain of 10, the estimated bandwidth is about 100 kHz.", "check":"What is the difference between slew-rate limitation and bandwidth limitation?", "answer":"Bandwidth describes small-signal frequency response; slew rate limits the maximum rate of change of a large output signal.", "pitfalls":["Treating gain-bandwidth product as exact for every frequency and load.","Confusing slew rate with small-signal bandwidth."]},
"ic741": {"worked_title":"741 operating-point sanity check", "worked_steps":["Identify the supply rails and input common-mode range.","Calculate the expected closed-loop output using the circuit equation.","Compare the expected input and output levels with the 741's datasheet limits for the stated supply and load."], "example":"A calculation that requires the output to reach exactly the positive supply rail should be flagged: a classic 741 is not a rail-to-rail op-amp.", "check":"Why should the 741 datasheet be consulted before finalising a design?", "answer":"Its offset, bias currents, slew rate, bandwidth, input range, output swing, load and supply limits are finite and affect the result.", "pitfalls":["Assuming rail-to-rail input or output.","Using typical values as guaranteed limits."]},
"inverting-amplifier": {"worked_title":"Calculate inverting gain", "worked_steps":["Use Av = −Rf/Rin for an ideal inverting amplifier in its linear region.","Substitute the feedback and input resistances in the same units.","Multiply the input voltage by Av and check output saturation."], "example":"Let Rin = 10 kΩ, Rf = 47 kΩ and Vin = 0.20 V. Av = −4.7, so Vout = −0.94 V.", "check":"What does the negative sign in the gain mean?", "answer":"The output is inverted by approximately 180 degrees relative to the input for a sinusoidal signal in the linear region.", "pitfalls":["Dropping the negative sign.","Forgetting that the result may saturate on real supply rails."]},
"non-inverting-amplifier": {"worked_title":"Calculate non-inverting gain", "worked_steps":["Use Av = 1 + Rf/Rg for the standard non-inverting configuration.","Substitute the feedback resistor and resistor to ground.","Multiply the input voltage by the gain and check output limits."], "example":"With Rf = 30 kΩ and Rg = 10 kΩ, Av = 1 + 3 = 4. A 0.5 V input ideally produces 2 V output.", "check":"Is the output inverted in a standard non-inverting amplifier?", "answer":"No. The output is in phase with the input when the circuit operates linearly.", "pitfalls":["Using the inverting gain formula.","Forgetting the unity-gain term."]},
"differential-amplifier": {"worked_title":"Differential output", "worked_steps":["Check that the two resistor ratios are matched as required by the circuit.","Identify which input is subtracted from which; follow the diagram's polarity.","Apply the matched-ratio gain equation and state the sign."], "example":"For a matched-ratio circuit with R2/R1 = 5, V2 = 0.8 V and V1 = 0.3 V, Vout = 5(0.8 − 0.3) = 2.5 V.", "check":"Why do resistor-ratio mismatches harm common-mode rejection?", "answer":"They make common-mode input components appear differentially at the output instead of cancelling ideally.", "pitfalls":["Reversing the input subtraction order.","Assuming CMRR remains ideal with mismatched resistors."]},
"instrumentation-amplifier": {"worked_title":"Small sensor signal with common-mode voltage", "worked_steps":["Separate the wanted differential signal from the common-mode voltage shared by both inputs.","Use the instrumentation amplifier's gain equation for the actual topology or IC.","Check input common-mode range, output range and reference-pin requirements."], "example":"A sensor produces 12 mV differential signal on top of a 1.2 V common-mode level. The desired quantity is the 12 mV difference; gain should amplify that difference while rejecting the shared level within the amplifier's limits.", "check":"Why are instrumentation amplifiers common in sensor interfaces?", "answer":"They combine high input impedance with high common-mode rejection and convenient gain setting.", "pitfalls":["Applying a generic gain equation to a different topology.","Ignoring input common-mode and output swing limits."]},
"ac-amplifier": {"worked_title":"Interpret AC gain", "worked_steps":["Find input and output amplitudes at the frequency of interest.","Calculate voltage gain as output amplitude divided by input amplitude.","Check whether coupling capacitors or device bandwidth alter gain at that frequency."], "example":"An input sinusoid of 100 mV peak produces 1.5 V peak output. The magnitude of voltage gain is 1.5/0.1 = 15, provided neither signal is clipped.", "check":"Why can an AC amplifier's gain change with frequency?", "answer":"Coupling and bypass capacitors, feedback networks, parasitic capacitances and device bandwidth shape its frequency response.", "pitfalls":["Comparing peak input with RMS output.","Ignoring phase when the question asks for waveform relationship."]},
"differentiator": {"worked_title":"Differentiator output for a ramp", "worked_steps":["Use Vout = −Rf C(dVin/dt) for the ideal inverting differentiator.","Find the slope of the input ramp in volts per second.","Multiply by RfC and apply the inverting sign."], "example":"For Rf = 10 kΩ, C = 0.1 µF and input slope = 2 V/ms, RfC = 0.001 s and Vout = −2 V while that ramp slope is maintained.", "check":"What does an ideal differentiator do to a constant input?", "answer":"Its derivative is zero, so the ideal output is zero after transients; practical offsets and leakage can affect the result.", "pitfalls":["Using the input amplitude instead of its slope.","Ignoring high-frequency noise sensitivity of the ideal circuit."]},
"integrator": {"worked_title":"Integrator output for a constant input", "worked_steps":["Use Vout = −(1/RC)∫Vin dt, including any initial output condition if supplied.","For constant Vin, replace the integral with Vin × elapsed time.","Check whether the computed ramp remains within the output limits."], "example":"With R = 100 kΩ, C = 0.1 µF and Vin = 0.2 V, the ideal slope is −Vin/(RC) = −20 V/s. After 10 ms, the output changes by −0.2 V.", "check":"What waveform does a constant input ideally produce at an integrator output?", "answer":"A linear ramp, with slope determined by input voltage and RC.", "pitfalls":["Forgetting the negative sign.","Ignoring saturation and the initial capacitor voltage."]},
"comparators": {"worked_title":"Threshold decision", "worked_steps":["Identify the non-inverting and inverting input voltages.","Compare V+ with V−.","State the output polarity using the device's output-stage and supply assumptions."], "example":"If V+ = 2.4 V and V− = 2.0 V, the comparator tends toward its high output state. The actual high level depends on the device and load.", "check":"Why is a comparator normally not analysed using a linear closed-loop gain equation?", "answer":"It is commonly operated open-loop as a switching device, driving toward an output limit according to input polarity.", "pitfalls":["Assuming a perfect output rail level.","Leaving unused inputs or reference nodes undefined."]},
"schmitt-trigger": {"worked_title":"Use hysteresis", "worked_steps":["Determine the upper and lower switching thresholds from the positive-feedback network.","Compare the input against the threshold corresponding to the current output state.","After switching, use the other threshold; the threshold changes because feedback changes the reference."], "example":"If a design has upper threshold +2 V and lower threshold −2 V, an input rising through +2 V changes state; on the way down it changes back at −2 V.", "check":"What is the hysteresis width in that example?", "answer":"4 V, calculated as upper threshold minus lower threshold.", "pitfalls":["Using only one threshold for both directions.","Forgetting output saturation affects threshold calculations."]},
"voltage-regulators": {"worked_title":"Estimate linear-regulator heat", "worked_steps":["Calculate the voltage dropped across the regulator: Vin − Vout.","Multiply the drop by load current to estimate pass-device dissipation.","Check package thermal resistance, ambient temperature and required heat sinking."], "example":"For 12 V input, 5 V output and 0.2 A load, approximate dissipation is (12−5)×0.2 = 1.4 W, which may require thermal analysis.", "check":"Why is dropout voltage important?", "answer":"The regulator needs sufficient input-to-output headroom to maintain regulation.", "pitfalls":["Checking only current rating and ignoring heat.","Assuming a regulator can always regulate when Vin is close to Vout."]},
"ic723": {"worked_title":"Plan a 723 regulator design", "worked_steps":["Identify the required output range and load current.","Choose the 723 configuration and external pass-element arrangement described in the source circuit.","Calculate feedback/reference components from that topology and verify current-limit and thermal conditions."], "example":"A 723-based design should not be finalised from the IC name alone: the feedback divider, pass element and current-limiting network determine the actual output and load capability.", "check":"Why must the circuit topology be known before calculating the 723 output?", "answer":"Different configurations use different reference, feedback, pass-transistor and current-limit connections.", "pitfalls":["Mixing equations from different regulator configurations.","Ignoring external transistor ratings and safe operating area."]},
"three-terminal-regulators": {"worked_title":"Select a three-terminal regulator", "worked_steps":["Compare required output voltage and current with the regulator variant.","Check input voltage, dropout, maximum dissipation and thermal protection.","Choose input/output capacitors as recommended by the specific datasheet."], "example":"A 9 V source cannot reliably supply a 9 V output through a linear regulator that requires additional headroom; choose adequate input headroom or a suitable alternative topology.", "check":"What happens when regulator dissipation exceeds the package's thermal capability?", "answer":"The device may overheat and enter thermal shutdown or be damaged if protections and limits are exceeded.", "pitfalls":["Assuming all 78xx/79xx variants have identical ratings.","Omitting recommended bypass capacitors."]},
# UNIT II — FILTERS, 555, PLL
"active-filters": {"worked_title":"First-order cutoff frequency", "worked_steps":["Identify the resistance and capacitance that set the pole in the given circuit.","Use fc = 1/(2πRC) for a simple first-order RC pole.","Check units: ohms multiplied by farads gives seconds."], "example":"For R = 10 kΩ and C = 10 nF, RC = 100 µs and fc ≈ 1/(2π×100 µs) ≈ 1.59 kHz.", "check":"What does the cutoff frequency represent for a standard first-order filter?", "answer":"It is the pole frequency where the magnitude is approximately 1/√2 of passband magnitude, or −3 dB, for the standard response.", "pitfalls":["Mixing nF and µF.","Assuming every filter topology has the same transfer function."]},
"band-pass-filter": {"worked_title":"Calculate bandwidth", "worked_steps":["Identify the lower cutoff fL and upper cutoff fH.","Calculate BW = fH − fL.","If requested, calculate the geometric centre frequency using √(fL fH) for the conventional band definition."], "example":"For fL = 500 Hz and fH = 2.5 kHz, bandwidth = 2,000 Hz and geometric centre frequency ≈ 1.118 kHz.", "check":"Which frequencies does an ideal band-pass filter attenuate?", "answer":"Frequencies well below the lower cutoff and well above the upper cutoff.", "pitfalls":["Adding cutoff frequencies instead of subtracting.","Confusing bandwidth with centre frequency."]},
"band-reject-filter": {"worked_title":"Notch frequency estimate", "worked_steps":["Read lower and upper cutoff frequencies from the problem.","Calculate the geometric centre f0 = √(fL fH) when that definition applies.","State the rejected band and the frequencies passed outside it."], "example":"For fL = 900 Hz and fH = 1.1 kHz, f0 ≈ √(990,000) ≈ 995 Hz, close to 1 kHz.", "check":"How does a notch filter differ from a low-pass filter?", "answer":"A notch rejects a limited band around a target frequency; a low-pass attenuates frequencies above its cutoff.", "pitfalls":["Treating the centre frequency as the bandwidth.","Calling every band-reject filter a narrow notch filter."]},
"all-pass-filter": {"worked_title":"Separate magnitude and phase", "worked_steps":["Inspect the magnitude response separately from phase response.","For an ideal all-pass design, magnitude remains constant over the intended band.","Describe how phase changes with frequency for the selected topology."], "example":"An ideal all-pass network may keep the sinusoid's amplitude unchanged while introducing a frequency-dependent phase shift; it is useful for phase equalisation rather than amplitude selection.", "check":"Does an all-pass filter ideally remove a frequency band?", "answer":"No. Its main intended effect is phase shaping while preserving magnitude.", "pitfalls":["Assuming all-pass means zero phase shift.","Ignoring real component tolerance and finite op-amp bandwidth."]},
"first-order-lpf": {"worked_title":"Low-pass cutoff example", "worked_steps":["Use fc = 1/(2πRC) for the first-order RC pole in the stated topology.","Calculate the passband behaviour below cutoff and attenuation above cutoff.","For a first-order response, note the asymptotic roll-off of about 20 dB/decade."], "example":"R = 15.9 kΩ and C = 10 nF give a cutoff close to 1 kHz.", "check":"What is the approximate magnitude at cutoff relative to passband for a standard first-order response?", "answer":"About 0.707 of passband amplitude, equivalent to −3 dB.", "pitfalls":["Applying the passive RC formula without checking active topology and gain.","Confusing frequency ratio per octave and per decade."]},
"first-order-hpf": {"worked_title":"High-pass cutoff example", "worked_steps":["Identify the series capacitor and resistance that set the first-order pole in the given circuit.","Use fc = 1/(2πRC) when the simple RC relationship applies.","Explain that low frequencies are attenuated and high frequencies pass within the op-amp bandwidth."], "example":"For R = 10 kΩ and C ≈ 15.9 nF, the cutoff is about 1 kHz.", "check":"What happens to a steady DC input after the transient in a simple first-order high-pass network?", "answer":"The steady DC component is attenuated toward zero in the ideal capacitive-coupling model.", "pitfalls":["Describing it as passing DC.","Ignoring the op-amp's upper bandwidth limit."]},
"triangular-generator": {"worked_title":"Understand the triangle-wave loop", "worked_steps":["A Schmitt-trigger stage sets upper and lower switching thresholds.","The integrator ramps while the comparator output is at one polarity.","When the ramp reaches a threshold, the comparator changes state and reverses the ramp slope."], "example":"If the ramp reaches +VTH, the comparator switches; the integrator then ramps toward −VTH. Repeated switching creates a triangular output at the integrator and a square-like output at the Schmitt stage.", "check":"Which block normally creates the linear ramp?", "answer":"The integrator.", "pitfalls":["Confusing the comparator square output with the integrator triangle output.","Ignoring threshold symmetry when estimating waveform symmetry."]},
"sawtooth-generator": {"worked_title":"Interpret the sawtooth waveform", "worked_steps":["Identify the slow ramp interval and the fast reset interval in the circuit.","Determine whether the ramp is generated by a constant-current capacitor or another timing network.","Use the actual charging current and capacitance to calculate slope if those values are provided."], "example":"For a capacitor charged by a nearly constant 100 µA into 10 nF, dV/dt = I/C = 10,000 V/s, so a 1 V ramp takes about 100 µs before reset.", "check":"What feature distinguishes a sawtooth from a symmetric triangular wave?", "answer":"The ramp in one direction and the rapid return/reset are typically unequal in duration.", "pitfalls":["Assuming both slopes have equal magnitude.","Ignoring transistor/reset-switch recovery time."]},
"square-wave-generator": {"worked_title":"Recognise oscillator feedback", "worked_steps":["Identify the positive-feedback thresholds and the RC timing path.","Track capacitor charging/discharging toward the switching threshold.","Use the exact topology's timing equation rather than a memorised equation for a different oscillator."], "example":"In a relaxation oscillator, the output switches when the timing capacitor reaches a threshold; the capacitor then moves toward the opposite threshold and the cycle repeats.", "check":"What role does positive feedback play in the op-amp relaxation oscillator?", "answer":"It establishes switching thresholds and regenerative transitions between output states.", "pitfalls":["Using the 555 astable equation for an op-amp oscillator.","Assuming a perfect 50% duty cycle without checking topology."]},
"ic555-functional": {"worked_title":"Read the 555 internal levels", "worked_steps":["The three nominally equal internal resistors form a divider across the supply.","The lower comparator uses a reference near VCC/3 and the upper comparator uses a reference near 2VCC/3.","The comparator outputs control a latch; the latch controls the output stage and discharge transistor."], "example":"With VCC = 9 V, the nominal divider levels are about 3 V and 6 V.", "check":"What is the purpose of the discharge transistor?", "answer":"It provides a controlled path to discharge the external timing capacitor in the appropriate timer state.", "pitfalls":["Swapping trigger and threshold functions.","Treating the divider thresholds as exact under every variant and condition."]},
"ic555-monostable": {"worked_title":"Calculate monostable pulse width", "worked_steps":["Identify the timing resistor R and capacitor C.","Use T ≈ 1.1RC for the classic 555 monostable configuration.","Convert R and C to base SI units before calculating."], "example":"R = 100 kΩ and C = 10 µF gives T ≈ 1.1×100,000×0.00001 = 1.1 s.", "check":"How many stable output states does a monostable have?", "answer":"One stable state; a trigger produces a temporary pulse before the circuit returns to its stable state.", "pitfalls":["Using kΩ and µF without careful unit conversion.","Assuming the pulse begins without a valid trigger event."]},
"ic555-astable": {"worked_title":"Calculate classic 555 astable timing", "worked_steps":["Use TH ≈ 0.693(RA+RB)C and TL ≈ 0.693RBC for the classic circuit.","Add high and low intervals to find period T.","Calculate f ≈ 1/T; actual duty cycle depends on topology and component values."], "example":"For RA = 10 kΩ, RB = 10 kΩ and C = 10 µF: TH ≈ 0.139 s, TL ≈ 0.0693 s, T ≈ 0.208 s and f ≈ 4.8 Hz.", "check":"Why is the classic two-resistor astable duty cycle typically greater than 50%?", "answer":"The capacitor charges through RA+RB but discharges through RB only, so the high interval is longer than the low interval when RA is positive.", "pitfalls":["Using only one interval to calculate frequency.","Forgetting the capacitor charge and discharge paths differ."]},
"ic555-applications": {"worked_title":"Choose a 555 mode", "worked_steps":["Decide whether the task needs one triggered pulse or continuous oscillation.","Use monostable mode for a single timed pulse after a trigger; use astable mode for a repeating waveform.","Select R and C from the target timing and verify trigger, reset and output-load conditions."], "example":"A pushbutton-triggered 1-second indicator pulse is naturally described by a monostable design; a continuously blinking LED is naturally described by an astable design.", "check":"Which mode is suited to a repeating clock-like waveform?", "answer":"Astable mode.", "pitfalls":["Choosing astable mode for a single one-shot pulse without additional gating.","Ignoring output current and LED resistor requirements."]},
"ic565-pll": {"worked_title":"Trace the IC 565 PLL loop", "worked_steps":["The phase detector compares the input signal with the feedback signal.","The loop filter smooths the detector output to control the VCO.","The VCO output is fed back to the comparator input as shown in the course circuit."], "example":"If the VCO is running below the input frequency, the phase detector and loop filter produce a control change that drives the VCO toward lock, assuming the loop is within its capture range.", "check":"Name the main functional blocks of a basic PLL.", "answer":"Phase detector, loop/low-pass filter, and voltage-controlled oscillator; an amplifier or buffer may also be shown in a particular IC block diagram.", "pitfalls":["Confusing capture range with lock range.","Omitting the external feedback connection when following the supplied IC 565 diagram."]},
"pll-principle": {"worked_title":"Explain PLL lock", "worked_steps":["At first, the reference and VCO feedback may differ in frequency and phase.","The phase detector creates an error signal related to phase difference.","The filtered error adjusts the VCO until the loop settles into a locked condition, if the input lies within the circuit's capabilities."], "example":"A locked loop tracks small changes in input frequency by adjusting its VCO control voltage, within its lock range and dynamic limits.", "check":"Does lock mean the input and VCO output must have zero phase difference?", "answer":"Not necessarily. A steady phase difference can be required to produce the control voltage that maintains the locked frequency.", "pitfalls":["Claiming a PLL always locks to any input frequency.","Ignoring loop-filter dynamics and stability."]},
"ic565-applications": {"worked_title":"Match PLL applications to functions", "worked_steps":["Identify whether the application needs frequency tracking, demodulation, synchronisation, or frequency multiplication.","Trace how the input signal reaches the phase detector and how the VCO output is returned.","For multiplication, identify the divider or feedback ratio described by the circuit."], "example":"If a feedback divider returns VCO frequency divided by N to the phase detector, lock can occur when fVCO/N equals the reference frequency, so fVCO ≈ N fref under ideal locked conditions.", "check":"Why is a divider inserted into a PLL feedback path for frequency multiplication?", "answer":"It lets the VCO operate at a multiple of the reference frequency while the divided feedback matches the reference.", "pitfalls":["Forgetting that the divider changes the loop's frequency relationship.","Assuming an application works outside the IC's specified frequency range."]},
# UNIT III — DATA CONVERTERS
"data-converter-intro": {"worked_title":"Count the code combinations", "worked_steps":["Read the converter's bit resolution N.","Calculate the number of possible binary codes as 2^N.","Distinguish code count from analog step size and conversion accuracy."], "example":"A 10-bit converter has 2^10 = 1,024 possible output codes.", "check":"Does 10-bit resolution alone guarantee 10-bit absolute accuracy?", "answer":"No. Accuracy also depends on offset, gain, linearity, reference, noise and other errors.", "pitfalls":["Treating resolution and accuracy as synonyms.","Ignoring the stated full-scale range convention."]},
"basic-dac": {"worked_title":"Relate code and output", "worked_steps":["Convert the input bit pattern to its unsigned integer value when that convention is used.","Identify the DAC's reference voltage and output scaling/polarity.","Apply the topology-specific transfer equation and check full-scale convention."], "example":"For a simple ideal unipolar 8-bit DAC with LSB = 1 V/256, code 64 gives 64/256 V = 0.25 V before any circuit-specific gain or offset.", "check":"Why should a DAC transfer equation state its full-scale convention?", "answer":"Different definitions use 2^N or 2^N−1 in scaling, so the same code can be associated with different stated LSB/full-scale conventions.", "pitfalls":["Assuming every DAC has positive output polarity.","Using the wrong reference or code convention."]},
"weighted-resistor-dac": {"worked_title":"Binary weighted contributions", "worked_steps":["Identify each bit's resistor and whether the bit is logic high or low.","Calculate each input branch contribution to the summing node.","Add contributions with the inverting summing-amplifier sign and the given reference voltage."], "example":"For an ideal 4-bit binary-weighted network, the MSB contribution is eight times the LSB contribution. If bit weights are 8, 4, 2 and 1 units, code 1011 contributes 8+0+2+1 = 11 units before output scaling.", "check":"What is a major practical weakness of a weighted-resistor DAC?", "answer":"It requires a wide range of accurately matched resistor values, especially as resolution grows.", "pitfalls":["Treating the MSB and LSB as equal contributions.","Ignoring inverting summing-amplifier polarity."]},
"r2r-ladder-dac": {"worked_title":"Interpret an R-2R ladder", "worked_steps":["Mark the digital input bits and the reference/ground state for each switch.","Use the repeated R and 2R network to track binary-weighted contributions.","Apply the output polarity and scale from the exact ladder diagram."], "example":"In a 4-bit ideal ladder, the MSB contribution is conventionally weighted four times the next bit and eight times the LSB relative to the LSB unit, according to the chosen output scaling.", "check":"Why is an R-2R ladder attractive compared with a binary-weighted resistor network?", "answer":"It uses only two resistor values, which simplifies matching and fabrication.", "pitfalls":["Reading bit order backwards.","Using a transfer equation from a different ladder termination or op-amp topology."]},
"inverted-r2r-dac": {"worked_title":"Analyse the inverted ladder carefully", "worked_steps":["Start from the exact inverted R-2R schematic in the unit notes.","Label each switch state and follow the current path for each bit.","Derive output polarity and weighting from that circuit rather than copying a standard R-2R formula."], "example":"When the ladder or op-amp connection is inverted, output polarity and the meaning of logic-high switch positions can differ from the standard ladder. Draw the bit-current contributions before simplifying.", "check":"Why should the inverted R-2R transfer equation be derived from the provided circuit?", "answer":"The term can refer to a particular connection arrangement; polarity and scale depend on the actual schematic.", "pitfalls":["Assuming every inverted ladder has the same sign and reference connection.","Skipping the switch-state diagram."]},
"parallel-comparator-adc": {"worked_title":"Comparator count", "worked_steps":["Read the required output resolution N.","Calculate 2^N distinct codes.","For a conventional flash ADC, calculate 2^N−1 threshold comparators."], "example":"A 3-bit flash ADC has 8 codes and typically 7 threshold comparators.", "check":"Why is a flash ADC fast?", "answer":"Its threshold comparisons occur in parallel instead of testing one code at a time.", "pitfalls":["Using 2^N comparators instead of 2^N−1 for the conventional architecture.","Ignoring encoder and comparator matching requirements."]},
"counter-adc": {"worked_title":"Estimate counter ADC conversion time", "worked_steps":["Determine the maximum counter value for the given N-bit converter.","Divide the maximum count by the clock frequency to estimate a worst-case count interval.","Include comparator and control delays if the problem requests a more complete estimate."], "example":"An 8-bit counter ADC can require up to 255 count steps under a zero-start convention. At a 100 kHz clock, 255 steps take about 2.55 ms, excluding extra overhead.", "check":"Why does conversion time depend on input level in a counter ADC?", "answer":"The counter stops when the DAC output reaches or crosses the sampled input, so higher inputs require more counts.", "pitfalls":["Assuming conversion time is fixed for all input levels.","Ignoring the sampled input and comparator stopping condition."]},
"sar-adc": {"worked_title":"Successive approximation as binary search", "worked_steps":["Set the MSB trial bit and compare the DAC trial output with the input.","Keep or clear that bit based on the comparison.","Repeat with each lower bit until all N bits have been tested."], "example":"For a 4-bit conversion, the SAR tests four bit positions in order. It narrows the candidate range each cycle rather than counting through all 16 codes.", "check":"How many main bit decisions are needed for an N-bit SAR conversion?", "answer":"Approximately N decisions, plus acquisition and implementation-specific overhead.", "pitfalls":["Starting at the LSB rather than the MSB in the standard algorithm.","Ignoring sample-and-hold requirements for changing inputs."]},
"dual-slope-adc": {"worked_title":"Understand integration intervals", "worked_steps":["Integrate the unknown input for a fixed time T1.","Switch to a known reference of opposite polarity.","Measure the deintegration time T2 required to return to the baseline; under the ideal model, the ratio relates T2 to input/reference."], "example":"With fixed integration time, doubling a positive input ideally doubles the deintegration interval when the reference magnitude remains constant.", "check":"Why is dual-slope conversion valued in digital multimeters?", "answer":"Its integration process can reject periodic interference and reduce sensitivity to many integrator component tolerances.", "pitfalls":["Reversing the reference polarity in the explanation.","Confusing the fixed integration interval with the measured deintegration interval."]},
"dac-specifications": {"worked_title":"Resolution and LSB size", "worked_steps":["Identify N and the specified full-scale range.","Use the convention given by the course question to calculate the LSB step.","Keep resolution, accuracy, linearity and settling time as separate specifications."], "example":"If a 10-bit unipolar converter uses a 0–5.12 V step-size convention, 5.12/1024 = 5 mV per code step.", "check":"What does settling time describe?", "answer":"The time required for the output to enter and remain within a specified error band after a code change.", "pitfalls":["Mixing endpoint full-scale definitions.","Assuming small LSB means small total error automatically."]},
"adc-specifications": {"worked_title":"Ideal quantisation step", "worked_steps":["Read the number of bits and full-scale input range.","Calculate the ideal code width under the convention specified in the problem.","Distinguish quantisation error from offset, gain, INL, DNL and noise."], "example":"For an ideal 8-bit ADC spanning a 0–2.56 V range with 2^N code widths, one LSB is 2.56/256 = 10 mV.", "check":"What is the usual ideal quantisation-error bound for a uniform quantiser?", "answer":"Approximately ±0.5 LSB under the standard rounding model, subject to the converter's coding convention.", "pitfalls":["Calling quantisation error the only ADC error.","Ignoring sample rate and input bandwidth requirements."]},
# UNIT IV — COMBINATIONAL LOGIC
"ttl-74xx": {"worked_title":"Compare TTL specifications", "worked_steps":["Identify the exact 74-series device and suffix; different families have different ratings.","Check supply voltage, VIH/VIL, VOH/VOL, propagation delay, current and fan-out.","Confirm compatibility with the devices connected to each input and output."], "example":"Do not infer exact current drive from the label '74XX' alone; the datasheet for the selected part and family determines valid load conditions.", "check":"Why is logic-level compatibility important when connecting TTL and CMOS?", "answer":"Their guaranteed input thresholds and output voltage/current capabilities may differ.", "pitfalls":["Treating all 74-series families as electrically identical.","Leaving CMOS inputs floating."]},
"cmos-40xx": {"worked_title":"Check CMOS supply and input levels", "worked_steps":["Find the specific 40XX device and its supported supply range.","Check the input thresholds at that supply voltage.","Review output drive, propagation delay, unused inputs and decoupling recommendations."], "example":"A CMOS gate's speed and output current capability can vary with supply voltage and load, so a logic diagram alone does not prove timing compatibility.", "check":"What should be done with unused CMOS inputs?", "answer":"Tie them to a defined valid logic level rather than leaving them floating.", "pitfalls":["Assuming CMOS thresholds are fixed at one supply voltage.","Ignoring ESD handling and decoupling."]},
"code-converters": {"worked_title":"Build a code-converter truth table", "worked_steps":["List every valid input code in the required range.","Write the required output code beside each input.","Derive each output Boolean function and simplify it, preserving invalid-input assumptions."], "example":"For a binary-to-Gray converter, the MSB is unchanged and each lower Gray bit is the XOR of adjacent binary bits: G = B XOR (B shifted right by one).", "check":"Why is a truth table a useful first step in code-converter design?", "answer":"It defines the required input-output mapping before Boolean simplification and implementation.", "pitfalls":["Skipping invalid or unused code conditions.","Mixing bit numbering conventions."]},
"decoders": {"worked_title":"Count decoder outputs", "worked_steps":["Identify the number n of binary input lines.","Calculate the possible output lines as 2^n for a full decoder.","Check enable pins and active-low/active-high output notation in the IC truth table."], "example":"A 3-to-8 decoder has 3 binary inputs and up to 8 decoded output lines.", "check":"What is the function of an enable input?", "answer":"It permits or inhibits the decoder operation according to the device's specified active level.", "pitfalls":["Assuming all outputs are active-high.","Ignoring enable-pin conditions."]},
"led-lcd-decoders": {"worked_title":"Match decoder to display", "worked_steps":["Identify the display technology and common-anode/common-cathode or LCD requirements.","Match the input code and segment truth table to the driver IC.","Check current limiting for LEDs and the required drive waveform for LCD segments."], "example":"A segment LED must have a suitable current-limiting method; an LCD segment cannot generally be driven as if it were a DC LED because sustained DC can damage the display.", "check":"Why are LED and LCD driver requirements not interchangeable?", "answer":"LEDs require current drive, while LCDs use an alternating drive scheme to avoid a sustained DC component.", "pitfalls":["Using the wrong common-anode/common-cathode logic.","Driving LED segments without current limiting."]},
"encoders": {"worked_title":"Encode one active input", "worked_steps":["Confirm exactly one input is asserted for a basic encoder.","Map that input index to its binary output code.","If simultaneous inputs are possible, determine whether the circuit defines priority or an invalid condition."], "example":"In a simple 4-to-2 encoder, activating input line 2 (with indexing from 0) produces binary output 10, under the chosen convention.", "check":"What problem occurs if multiple inputs are active in a basic encoder?", "answer":"The output can become ambiguous unless the design specifies priority or otherwise handles multiple asserted inputs.", "pitfalls":["Using one-based and zero-based input numbering inconsistently.","Assuming priority exists in a basic encoder."]},
"priority-encoders": {"worked_title":"Resolve simultaneous inputs", "worked_steps":["List the active inputs and the defined priority order.","Select the highest-priority active input.","Translate its index to the output code and check any valid or group-select output."], "example":"If inputs 1 and 3 are both active and input 3 has higher priority, the output represents input 3.", "check":"Why is a valid output often useful?", "answer":"It distinguishes a valid encoded input from the condition where no input is active.", "pitfalls":["Assuming the highest numerical input always has priority without checking the datasheet.","Ignoring active-low input conventions."]},
"multiplexers": {"worked_title":"Select line count", "worked_steps":["Count the number of data inputs M.","For M = 2^n inputs, use n select lines.","Use the select code to identify which input appears at the output."], "example":"A 8-to-1 multiplexer needs 3 select lines because 2^3 = 8.", "check":"Can a multiplexer implement a Boolean function?", "answer":"Yes. With select variables and appropriately assigned data inputs, it can realise many Boolean functions.", "pitfalls":["Reading select-bit order incorrectly.","Ignoring enable input polarity."]},
"demultiplexers": {"worked_title":"Route a data input", "worked_steps":["Identify the input signal, select lines and output count.","Decode the select value to determine the active destination output.","Check whether unselected outputs are low, high or otherwise defined by the device."], "example":"A 1-to-8 demultiplexer uses three select bits to route the input to one of eight output paths.", "check":"How does a demultiplexer differ from a multiplexer?", "answer":"A multiplexer selects one of many inputs to one output; a demultiplexer routes one input to one of many outputs.", "pitfalls":["Swapping data-input and data-output roles.","Assuming inactive output levels without checking the IC."]},
"priority-generators-checkers": {"worked_title":"Design from conditions", "worked_steps":["Write the exact priority or checking rule as a truth table.","Mark valid and invalid input combinations.","Derive output functions and test edge cases against the intended code convention."], "example":"For a parity checker, compute the parity of the received data bits and compare it with the received parity bit; a mismatch indicates a parity error under the chosen even/odd convention.", "check":"Does a parity check detect every possible multi-bit error?", "answer":"No. Some even-numbered bit errors can preserve parity and go undetected.", "pitfalls":["Not stating even or odd parity.","Assuming parity provides correction rather than simple error detection."]},
"parallel-binary-adder": {"worked_title":"Full-adder calculation", "worked_steps":["For each bit, calculate S = A XOR B XOR Cin.","Calculate Cout = AB + ACin + BCin.","Pass each carry to the next higher bit in a ripple-carry arrangement."], "example":"For A=1, B=1 and Cin=0, S=0 and Cout=1 because 1+1+0 equals binary 10.", "check":"What is the main delay source in a ripple-carry adder?", "answer":"Carry propagation through successive stages.", "pitfalls":["Forgetting the carry-in.","Confusing sum bit with carry-out."]},
"parallel-binary-subtractor": {"worked_title":"Subtract with two's complement", "worked_steps":["Choose a fixed bit width.","Invert B and add one to form its two's complement.","Add A to that value and interpret the result at the chosen width, noting carry/borrow convention."], "example":"Using 4 bits, 5 − 3 = 0101 + (two's complement of 0011, which is 1101) = 1 0010. Discarding the carry gives 0010, or decimal 2.", "check":"Why must bit width be specified in two's-complement arithmetic?", "answer":"Negation and overflow interpretation depend on the fixed representation width.", "pitfalls":["Failing to add the +1 after complementing.","Interpreting carry-out as the same thing as signed overflow."]},
"magnitude-comparators": {"worked_title":"Compare binary words", "worked_steps":["Compare the most significant bits first.","If those bits differ, they determine the relationship.","If equal, move to the next bit until a difference appears or all bits match."], "example":"For 4-bit values A=1010 (10) and B=1001 (9), the MSBs match and the next bits match; the first difference is at the third bit from the left, so A>B.", "check":"What does the equality output indicate?", "answer":"All compared bits are equal under the comparator's input and cascade conditions.", "pitfalls":["Comparing from the LSB first without a valid cascade scheme.","Ignoring cascade inputs on multi-bit comparator ICs."]},
# UNIT V — SEQUENTIAL LOGIC AND MEMORIES
"sequential-ics": {"worked_title":"Choose a sequential IC", "worked_steps":["Determine whether the task needs storage, counting, shifting or state control.","Check clock edge, asynchronous set/reset, active levels and output drive.","Read the timing diagram and setup/hold requirements before connecting signals."], "example":"Two ICs may both be described as flip-flops but differ in triggering edge, asynchronous controls and clear/set polarity; their symbols and timing diagrams must be checked.", "check":"What is the difference between combinational and sequential logic?", "answer":"Combinational output depends on current inputs; sequential output also depends on stored state and often on clock events.", "pitfalls":["Ignoring asynchronous reset behaviour.","Connecting a clock without considering edge polarity and timing."]},
"sr-flip-flop": {"worked_title":"SR truth table", "worked_steps":["Identify whether the implementation is NOR-based, NAND-based or clocked.","Read the active level of S and R from the circuit.","For the conventional active-high SR model: 00 holds, 10 sets, 01 resets, and 11 is forbidden/undefined."], "example":"For a conventional active-high SR latch, S=1 and R=0 sets Q=1; S=0 and R=1 resets Q=0.", "check":"Why must the SR forbidden condition be stated with its implementation?", "answer":"NAND-based active-low versions use different input conventions, so the truth table changes with polarity.", "pitfalls":["Using an active-high table for active-low inputs.","Treating the forbidden state as a normal stable operation."]},
"jk-flip-flop": {"worked_title":"JK next-state calculation", "worked_steps":["Read J and K at the active clock edge.","Apply hold for 00, reset for 01, set for 10, and toggle for 11 in the conventional JK model.","Account for edge-triggering or master-slave behaviour if the device specifies it."], "example":"If current Q=0 and J=K=1 at the active edge, next Q=1; at the next active edge with J=K=1, Q toggles back to 0.", "check":"What JK condition causes toggling?", "answer":"J=1 and K=1 at the active clock event.", "pitfalls":["Applying input changes continuously instead of at the active clock event.","Ignoring race-around concerns in level-sensitive implementations."]},
"d-flip-flop": {"worked_title":"Sample a D input", "worked_steps":["Identify the active clock edge.","Read D at that edge, provided setup and hold timing are satisfied.","The stored Q takes that value and retains it until another active event or asynchronous control."], "example":"If D=1 just before the active rising edge and timing requirements are met, Q becomes 1 after the clock-to-Q delay.", "check":"What is the next-state relation for a basic D flip-flop?", "answer":"Q(next)=D at the active clock edge, ignoring asynchronous controls.", "pitfalls":["Reading D at the wrong clock edge.","Ignoring setup and hold times."]},
"t-flip-flop": {"worked_title":"T flip-flop toggle sequence", "worked_steps":["If T=0 at the active edge, retain Q.","If T=1 at the active edge, invert Q.","Repeat this state update for each active clock event."], "example":"Starting from Q=0 with T held at 1, the sequence after successive active edges is 1, 0, 1, 0.", "check":"How can a T flip-flop be used as a divide-by-two stage?", "answer":"Hold T high so Q toggles at every active clock edge, producing half the clock frequency under ideal conditions.", "pitfalls":["Confusing T input with a toggle pulse independent of clock.","Ignoring reset initial state."]},
"synchronous-counters": {"worked_title":"Count states and bits", "worked_steps":["Determine the number of distinct states in the sequence.","Choose enough flip-flops so 2^n is at least the required state count.","Write the state-transition table and derive each next-state input function."], "example":"A 12-state counter needs at least 4 flip-flops because 2^3=8 is insufficient and 2^4=16 is enough.", "check":"Why do synchronous counter flip-flops share a clock?", "answer":"All state bits update from the same clock event, with combinational logic determining their next values.", "pitfalls":["Designing unused states without considering recovery.","Assuming synchronous means zero propagation delay."]},
"decade-counters": {"worked_title":"Design a decade sequence", "worked_steps":["List the desired states 0000 through 1001 for a standard BCD decade count.","Specify the transition from decimal 9 back to decimal 0.","Choose a synchronous or ripple implementation and derive reset/next-state logic from the selected topology."], "example":"A decade counter has ten valid states and therefore needs at least four state bits; six of the 16 possible 4-bit patterns are unused in a simple BCD sequence.", "check":"How many flip-flops are minimally required for ten states?", "answer":"Four, because three bits encode only eight states.", "pitfalls":["Allowing the count to continue into 1010 without intended recovery.","Confusing BCD decade count with a 16-state binary counter."]},
"shift-registers": {"worked_title":"Trace a serial shift", "worked_steps":["Draw the register stages and mark the direction of shifting.","At each active clock edge, transfer each stage's old value to the next stage.","Insert the serial input and observe the serial or parallel outputs after each clock."], "example":"For a 4-stage shift register initially 0000 with serial input 1 and shifting toward the rightmost stage, successive inserted ones move through the register; exact bit order depends on the diagram's shift direction.", "check":"What do SIPO and PISO mean?", "answer":"Serial-in parallel-out and parallel-in serial-out.", "pitfalls":["Reversing stage order.","Ignoring whether the output is taken before or after the active clock edge."]},
"rom-architecture": {"worked_title":"Calculate ROM capacity", "worked_steps":["Determine the number of address inputs A; there are 2^A addressable words.","Determine the output word width W bits.","Multiply word count by word width for total capacity."], "example":"A ROM with 8 address lines and 8 output bits stores 2^8×8 = 2,048 bits, or 256 bytes.", "check":"What does an address decoder select in a ROM?", "answer":"The stored word associated with the supplied address.", "pitfalls":["Confusing address lines with data-output lines.","Reporting bits as bytes without dividing by eight."]},
"rom-types-applications": {"worked_title":"Compare ROM technologies", "worked_steps":["Identify whether contents are fixed at manufacture, programmed once, or erasable/reprogrammable.","Compare the programming and erase method for the specific technology.","Choose the technology based on update needs, retention, endurance and system constraints."], "example":"PROM is generally programmable once; EPROM can be erased using ultraviolet light in traditional devices; EEPROM supports electrical erase/programming, with details depending on the device.", "check":"What is the key difference between PROM and EEPROM?", "answer":"PROM is generally one-time programmable, whereas EEPROM can be electrically erased and reprogrammed.", "pitfalls":["Assuming every ROM is impossible to update.","Treating flash and EEPROM erase granularity as identical in every device."]},
"ram-architecture": {"worked_title":"Calculate RAM organisation", "worked_steps":["Use the number of address lines to calculate addressable words.","Multiply by the bits per word to obtain capacity in bits.","Identify data, address, read/write and chip-enable signals in the memory interface."], "example":"A memory organised as 1K × 8 stores 1,024 words of 8 bits, giving 8,192 bits or 1 KiB.", "check":"What does 1K × 8 mean in memory organisation?", "answer":"1,024 addressable words, each 8 bits wide, under the usual binary memory convention.", "pitfalls":["Reading 1K × 8 as 1,000 bits.","Ignoring read/write timing and enable signals."]},
"static-ram": {"worked_title":"SRAM capacity and behaviour", "worked_steps":["Calculate capacity from word count and width if requested.","Explain that an SRAM bit is stored in a bistable cell while power is maintained.","Compare speed, density, cost and standby power with DRAM for the given application."], "example":"A 256 × 4 SRAM contains 1,024 bits. It normally does not require periodic refresh while powered, but it loses volatile data when power is removed.", "check":"Does SRAM retain data after power is removed?", "answer":"No. SRAM is volatile memory.", "pitfalls":["Calling SRAM non-volatile because it needs no refresh.","Ignoring that static operation still requires power to retain data."]},
"dynamic-ram": {"worked_title":"DRAM refresh concept", "worked_steps":["Explain that a DRAM cell stores information as charge.","Describe why leakage causes the stored level to decay over time.","Relate refresh control to maintaining data and note the density/complexity trade-off."], "example":"A DRAM system periodically reads/restores or otherwise refreshes rows according to the device's refresh protocol so charge loss does not corrupt stored bits.", "check":"Why does DRAM require refresh?", "answer":"The charge representing a bit leaks over time, so the stored information must be periodically restored.", "pitfalls":["Assuming refresh is needed only when a cell is read.","Comparing SRAM and DRAM without noting their different cell structures."]},
}


def lesson_detail(topic):
    """Return a topic-specific teaching panel for every catalogue entry."""
    detail = LESSON_BANK.get(topic.slug)
    if detail:
        return detail
    # Safe fallback for newly added catalogue topics: remains explicit about
    # the need to derive details from the actual circuit/logic convention.
    return {
        "worked_title": f"Study method: {topic.title}",
        "worked_steps": [
            f"Write a one-sentence definition of {topic.title} and identify the input, output and operating conditions.",
            "Redraw the circuit, truth table or block diagram from the relevant unit notes and label every signal.",
            "Derive the relationship from that labelled source diagram, then check units, polarity and operating limits."
        ],
        "example": f"For {topic.title}, first identify the exact circuit or IC configuration in the course notes. Use its stated assumptions and component labels to work from the inputs to the output; do not substitute an equation from a different topology.",
        "check": f"What should you identify before solving a question on {topic.title}?",
        "answer": "The exact circuit/logic convention, defined input and output signals, operating conditions, and the relevant equation or truth table.",
        "pitfalls": ["Applying a formula before checking the circuit configuration.", "Leaving out units, signal polarity or stated assumptions."]
    }
